"""Replay the requirements lock gate on parser cases and isolated Git fixtures."""

from pathlib import Path
import shutil
import subprocess
import sys
import unittest
from unittest import mock

from git_fixture import isolated_repository
import requirements_lock_gate as gate


ROOT = Path(__file__).resolve().parents[2]
GATE = Path(".config/embodied/requirements_lock_gate.py")
MKDOCS = Path(".config/mkdocs")
REUSE_LOCK = ".config/reuse/requirements.txt"
UV_HEADER = (
    "# This file was autogenerated by uv via the following command:\n"
    "#    uv pip compile --universal --generate-hashes --python-version=3.11.5 "
    "requirements.in --output-file=requirements.txt\n"
)
HASH = "    --hash=sha256:" + "0" * 64 + "\n"


def lock_text(entries, header=UV_HEADER):
    """Build a uv-style lock from (pin, via_lines) pairs below header."""
    body = "".join(f"{pin} \\\n{HASH}" + "".join(f"    {via}\n" for via in vias)
                   for pin, vias in entries)
    return header + body


class ParserTests(unittest.TestCase):
    def test_names_normalise_per_pep_503(self):
        """Verify case, underscores and dots collapse to one lower-case hyphen form."""
        for written, expected in (("PyYAML", "pyyaml"), ("mkdocs_material", "mkdocs-material"),
                                  ("a.b-_c", "a-b-c"), ("x", "x")):
            with self.subTest(name=written):
                self.assertEqual(gate.canonical_name(written), expected)

    def test_versions_drop_trailing_zero_release_parts_only(self):
        """Verify normal forms drop trailing zero release parts and other spellings give None."""
        for written, expected in (("13.1.0", "13.1"), ("2.0.0", "2"), ("0", "0"), ("0.0", "0"),
                                  ("10.21.2", "10.21.2"), ("1.0rc1", "1rc1"), ("1.0.0rc1", "1rc1"),
                                  ("2.0.post1.dev0", "2.post1.dev0"), ("1.0RC1", None),
                                  ("v1.0", None), ("1.0-post1", None), ("01.0", None),
                                  ("1.0a", None), ("1!1.0", None), ("1.0+cpu", None)):
            with self.subTest(version=written):
                self.assertEqual(gate.canonical_version(written), expected)

    def test_input_pins_refuse_versions_outside_normal_form(self):
        """Verify an input version PEP 440 would normalise is refused by name, never compared."""
        pins, errors = gate.input_pins("r.in", "mkdocs==1.6.1\nmkdocs-material==9.8.1-post1\n")
        self.assertEqual(pins, {"mkdocs": ("mkdocs==1.6.1", "1.6.1")})
        self.assertEqual(errors, ["r.in:2: version 9.8.1-post1 is not in PEP 440 normal form; "
                                  "write it as the lock spells it"])

    def test_input_pins_accept_comments_spacing_and_crlf(self):
        """Verify comments, spaces around == and CRLF line ends parse to name and version."""
        text = ("# header\r\n\r\nmkdocs==1.6.1  # trailing note\r\n"
                "Mkdocs_Material == 9.8.1\r\n")
        pins, errors = gate.input_pins("r.in", text)
        self.assertEqual(errors, [])
        self.assertEqual(pins, {
            "mkdocs": ("mkdocs==1.6.1", "1.6.1"),
            "mkdocs-material": ("Mkdocs_Material==9.8.1", "9.8.1"),
        })

    def test_input_pins_refuse_anything_but_exact_pins(self):
        """Verify ranges, includes, URLs, extras, markers and duplicates are errors, never skipped."""
        for line in ("mkdocs>=1.6", "mkdocs", "-r other.in", "-c constraints.txt",
                     "pkg @ https://example.invalid/pkg.whl", "mkdocs===1.6.1",
                     "mkdocs==1.*", "mkdocs==1.6.1,<2", "mkdocs-material[imaging]==9.8.1",
                     "pymdown-extensions==13.1 ; sys_platform == 'linux'",
                     "\ufeffmkdocs==1.6.1"):
            with self.subTest(line=line):
                pins, errors = gate.input_pins("r.in", f"{line}\n")
                self.assertEqual(pins, {})
                self.assertEqual(len(errors), 1)
                self.assertIn("r.in:1:", errors[0])
        _, errors = gate.input_pins("r.in", "mkdocs==1.6.1\nMkDocs==1.6.0\n")
        self.assertEqual(errors, ["r.in:2: MkDocs is pinned twice"])

    def test_lock_entries_read_pins_markers_and_input_annotations(self):
        """Verify both annotation forms record the input and markers keep one name."""
        text = lock_text([
            ("mkdocs==1.6.1", ["# via", "#   -r requirements.in", "#   mkdocs-material"]),
            ("pymdown-extensions==13.1", ["# via -r requirements.in"]),
            ("colorama==0.4.6 ; sys_platform == 'win32'", ["# via mkdocs"]),
            ("numpy==2.0 ; python_full_version < '3.12'", ["# via mkdocs"]),
            ("numpy==2.1 ; python_full_version >= '3.12'", ["# via mkdocs"]),
            ("mkdocs-minify-plugin==0.8.0", ["# via -r ./requirements.in"]),
            ("pyyaml==6.0RC1", ["# via mkdocs"]),
        ])
        versions, via, errors = gate.lock_entries("r.txt", text)
        self.assertEqual(errors, [])
        self.assertEqual(versions["numpy"], {"2": "2.0", "2.1": "2.1"})
        self.assertEqual(versions["colorama"], {"0.4.6": "0.4.6"})
        self.assertEqual(versions["pyyaml"], {"6.0RC1": "6.0RC1"})
        self.assertEqual(via, {"mkdocs": {"requirements.in"},
                               "mkdocs-minify-plugin": {"requirements.in"},
                               "pymdown-extensions": {"requirements.in"}})

    def test_lock_entries_refuse_unknown_lines(self):
        """Verify an index option or stray indented text is an error, never skipped."""
        for text in (UV_HEADER + "--index-url https://example.invalid\n",
                     UV_HEADER + "mkdocs==1.6.1 \\\n    stray\n"):
            with self.subTest(text=text.splitlines()[-1]):
                _, _, errors = gate.lock_entries("r.txt", text)
                self.assertEqual(len(errors), 1)

    def test_lock_header_classifies_uv_pip_compile_prelude_and_plain_text(self):
        """Verify uv and pip-compile headers are locks, a prelude is unchecked, prose is none."""
        pip_header = ("#\n# This file is autogenerated by pip-compile with Python 3.14\n"
                      "# by the following command:\n#\n"
                      "#    pip-compile --allow-unsafe --generate-hashes "
                      "--output-file=b.txt b.in\n#\n")
        self.assertEqual(gate.lock_header(UV_HEADER)[0], "lock")
        self.assertEqual(gate.lock_header(pip_header),
                         ("lock", "pip-compile --allow-unsafe --generate-hashes "
                                  "--output-file=b.txt b.in"))
        self.assertEqual(gate.lock_header("# SPDX\n\n" + UV_HEADER), ("unchecked", None))
        for prelude in ("# SPDX\n" * 20, "# SPDX\n\n" + "prose\n" * 20):
            with self.subTest(prelude_lines=prelude.count("\n")):
                self.assertEqual(gate.lock_header(prelude + UV_HEADER), ("unchecked", None))
        self.assertEqual(gate.lock_header("plain text\n# This file was not\n"), (None, None))
        self.assertEqual(gate.lock_header(UV_HEADER.splitlines()[0] + "\n"), ("lock", None))

    def test_command_inputs_resolve_against_the_lock_directory(self):
        """Verify inputs resolve beside the lock and a wrong output or no input fails."""
        command = gate.lock_header(UV_HEADER)[1]
        self.assertEqual(gate.command_inputs("a/b/requirements.txt", command),
                         (["a/b/requirements.in"], None))
        self.assertEqual(gate.command_inputs("requirements.txt", command),
                         (["requirements.in"], None))
        for path, line in (("a/other.txt", command),
                           ("requirements.txt", "uv pip compile --output-file=requirements.txt"),
                           ("requirements.txt", "uv pip compile 'unbalanced"),
                           ("requirements.txt", "uv venv requirements.in"),
                           ("requirements.txt", "uv pip compile -o requirements.txt requirements.in"),
                           ("requirements.txt", "uv pip compile --constraint c.txt "
                                                "requirements.in --output-file=requirements.txt"),
                           ("requirements.txt", "uv pip compile requirements.in "
                                                "--output-file=other.txt --output-file=requirements.txt"),
                           ("requirements.txt", "uv pip compile --no-annotate requirements.in "
                                                "--output-file=requirements.txt"),
                           ("requirements.txt", None)):
            with self.subTest(path=path, line=line):
                inputs, error = gate.command_inputs(path, line)
                self.assertIsNone(inputs)
                self.assertTrue(error.startswith(f"{path}: "))


class RepositoryTests(unittest.TestCase):
    def setUp(self):
        """Create an isolated temporary Git fixture holding a copy of the gate script."""
        self.repo, self.env = isolated_repository(self, "requirements-lock-")
        (self.repo / GATE).parent.mkdir(parents=True)
        shutil.copyfile(ROOT / GATE, self.repo / GATE)

    def git(self, *args):
        """Run git with *args in the fixture repository and return stdout bytes."""
        return subprocess.run(
            ["git", *args], cwd=self.repo, env=self.env, check=True,
            capture_output=True, timeout=10,
        ).stdout

    def track(self, path, text):
        """Write text to path in the fixture and stage it."""
        target = self.repo / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text, encoding="utf-8")
        self.git("add", "--", str(path))

    def run_gate(self):
        """Run the copied gate in the fixture repository and return the completed process."""
        return subprocess.run(
            [sys.executable, "-I", str(GATE)], cwd=self.repo, env=self.env,
            capture_output=True, text=True, timeout=30,
        )

    def copy_mkdocs_locks(self):
        """Stage copies of this repository's MkDocs inputs and locks in the fixture."""
        for name in ("requirements.in", "requirements.txt",
                     "build-requirements.in", "build-requirements.txt"):
            self.track(MKDOCS / name, (ROOT / MKDOCS / name).read_text(encoding="utf-8"))

    def test_repository_copy_passes(self):
        """Verify this repository's locks agree with exit 0 and its REUSE lock is named unchecked."""
        self.copy_mkdocs_locks()
        self.track(REUSE_LOCK, (ROOT / REUSE_LOCK).read_text(encoding="utf-8"))
        result = self.run_gate()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("pins agree with their inputs: .config/mkdocs/build-requirements.txt, "
                      ".config/mkdocs/requirements.txt\n", result.stdout)
        self.assertIn(f"not checked: {REUSE_LOCK}: lock header does not open the file", result.stdout)

    def test_byte_order_mark_fails(self):
        """Verify an input or lock opening with a UTF-8 byte order mark fails with exit 1."""
        lock = lock_text([("mkdocs==1.6.1", ["# via -r requirements.in"])])
        for name, text in (("requirements.in", "\ufeffmkdocs==1.6.1\n"), ("requirements.txt", "\ufeff" + lock)):
            with self.subTest(file=name):
                self.track("requirements.in", "mkdocs==1.6.1\n")
                self.track("requirements.txt", lock)
                self.track(name, text)
                result = self.run_gate()
                self.assertEqual(result.returncode, 1)
                self.assertIn(f"{name}: starts with a UTF-8 byte order mark", result.stderr)

    def test_tracked_listing_limits_fail_closed(self):
        """Verify a listing at the path and byte limits passes and one above either is an error."""
        self.track("a.in", "")
        self.track("b.in", "")
        listing = len("a.in\0b.in\0")
        cases = (((2, listing), None), ((1, listing), "listed 2 paths, above the 1 limit"),
                 ((2, listing - 1), f"wrote {listing} bytes, above the {listing - 1} byte limit"))
        for (max_paths, max_bytes), expected in cases:
            with self.subTest(max_paths=max_paths, max_bytes=max_bytes), \
                    mock.patch.object(gate, "MAX_TRACKED_PATHS", max_paths), \
                    mock.patch.object(gate, "MAX_LISTING_BYTES", max_bytes):
                paths, error = gate.tracked_paths(shutil.which("git"), self.repo, self.env)
                if expected is None:
                    self.assertEqual((paths, error), (["a.in", "b.in"], None))
                else:
                    self.assertIsNone(paths)
                    self.assertIn(expected, error)

    def test_inherited_git_repository_variables_are_ignored(self):
        """Verify GIT_DIR and GIT_WORK_TREE naming a clean repository cannot hide drift here."""
        other, _ = isolated_repository(self, "requirements-lock-other-")
        self.track("requirements.in", "mkdocs==1.6.0\n")
        self.track("requirements.txt", lock_text([("mkdocs==1.6.1", ["# via -r requirements.in"])]))
        result = subprocess.run(
            [sys.executable, "-I", str(GATE)], cwd=self.repo, capture_output=True, text=True,
            env={**self.env, "GIT_DIR": str(other / ".git"), "GIT_WORK_TREE": str(other)}, timeout=30,
        )
        self.assertEqual(result.returncode, 1, result.stdout)
        self.assertIn("requirements.in: mkdocs==1.6.0 but requirements.txt pins 1.6.1", result.stderr)

    def test_symbolic_link_input_fails_without_reading_its_target(self):
        """Verify a tracked input that is a symbolic link fails with exit 1 and its target unread."""
        (self.repo / "outside.txt").write_text("secret line\n", encoding="utf-8")
        (self.repo / "requirements.in").symlink_to("outside.txt")
        self.git("add", "--", "requirements.in")
        self.track("requirements.txt", lock_text([("mkdocs==1.6.1", ["# via -r requirements.in"])]))
        result = self.run_gate()
        self.assertEqual(result.returncode, 1)
        self.assertIn("requirements.in: is a symbolic link or resolves outside the checkout", result.stderr)
        self.assertNotIn("secret line", result.stderr)
        outside, _ = isolated_repository(self, "requirements-lock-outside-")
        (outside / "requirements.in").write_text("mkdocs==1.6.1\n", encoding="utf-8")
        (self.repo / "linked").symlink_to(outside, target_is_directory=True)
        text, error = gate.read_text(str(self.repo), "linked/requirements.in")
        self.assertIsNone(text)
        self.assertIn("linked/requirements.in: is a symbolic link or resolves outside the checkout", error)

    def test_dot_slash_annotation_still_reports_a_dropped_pin(self):
        """Verify a lock annotated -r ./requirements.in fails when the input drops that pin."""
        self.track("requirements.in", "mkdocs==1.6.1\n")
        self.track("requirements.txt", lock_text([
            ("mkdocs==1.6.1", ["# via -r requirements.in"]),
            ("pymdown-extensions==13.1", ["# via -r ./requirements.in"])]))
        result = self.run_gate()
        self.assertEqual(result.returncode, 1)
        self.assertIn("pymdown-extensions is annotated -r requirements.in, but requirements.in no longer pins it",
                      result.stderr)

    def test_input_marker_against_other_lock_marker_fails(self):
        """Verify a Linux-only input pin against a Windows-only lock entry fails with exit 1."""
        self.track("requirements.in", "pywin32-ctypes==0.2.3 ; sys_platform == 'linux'\n")
        self.track("requirements.txt", lock_text([
            ("pywin32-ctypes==0.2.3 ; sys_platform == 'win32'", ["# via -r requirements.in"])]))
        result = self.run_gate()
        self.assertEqual(result.returncode, 1)
        self.assertIn("requirements.in:1: not an exact name==version pin (extras and markers are refused)",
                      result.stderr)

    def test_lock_naming_non_input_file_fails(self):
        """Verify a lock whose header input is not a *.in file fails with exit 1."""
        header = UV_HEADER.replace("requirements.in --output", "pyproject.toml --output")
        self.track("pyproject.toml", "[project]\nname = 'x'\n")
        self.track("requirements.txt", lock_text([("mkdocs==1.6.1", [])], header=header))
        result = self.run_gate()
        self.assertEqual(result.returncode, 1)
        self.assertIn("requirements.txt: input pyproject.toml is not a *.in file", result.stderr)

    def test_planted_renovate_drift_fails(self):
        """Verify the lock-only bumps of pull requests 16 and 20 fail with exit 1."""
        for stale in ("mkdocs-material==9.8.0", "pymdown-extensions==12.3"):
            with self.subTest(stale=stale):
                self.copy_mkdocs_locks()
                source = self.repo / MKDOCS / "requirements.in"
                name = stale.split("==")[0]
                lines = [stale if line.startswith(f"{name}==") else line
                         for line in source.read_text(encoding="utf-8").splitlines()]
                self.track(MKDOCS / "requirements.in", "\n".join(lines) + "\n")
                result = self.run_gate()
                self.assertEqual(result.returncode, 1, result.stdout)
                self.assertIn(f".config/mkdocs/requirements.in: {stale} but "
                              ".config/mkdocs/requirements.txt pins", result.stderr)

    def test_pin_missing_from_lock_fails(self):
        """Verify an input pin with no lock entry fails with exit 1."""
        self.track("requirements.in", "mkdocs==1.6.1\nnew-plugin==1.0\n")
        self.track("requirements.txt", lock_text([("mkdocs==1.6.1", ["# via -r requirements.in"])]))
        result = self.run_gate()
        self.assertEqual(result.returncode, 1)
        self.assertIn("requirements.in: new-plugin==1.0 has no entry in requirements.txt",
                      result.stderr)

    def test_removed_pin_still_annotated_in_lock_fails(self):
        """Verify a lock entry still annotated -r for a dropped input pin fails with exit 1."""
        self.track("requirements.in", "mkdocs==1.6.1\n")
        self.track("requirements.txt", lock_text([
            ("mkdocs==1.6.1", ["# via -r requirements.in"]),
            ("old-plugin==2.0", ["# via -r requirements.in"]),
        ]))
        result = self.run_gate()
        self.assertEqual(result.returncode, 1)
        self.assertIn("requirements.txt: old-plugin is annotated -r requirements.in",
                      result.stderr)

    def test_input_without_lock_fails(self):
        """Verify a tracked input that no lock header names fails with exit 1."""
        self.track("docs/requirements.in", "mkdocs==1.6.1\n")
        result = self.run_gate()
        self.assertEqual(result.returncode, 1)
        self.assertIn("docs/requirements.in: no tracked lock names this input", result.stderr)

    def test_lock_naming_untracked_input_fails(self):
        """Verify a lock whose header input is not tracked fails with exit 1."""
        self.track("requirements.txt", lock_text([("mkdocs==1.6.1", ["# via -r requirements.in"])]))
        (self.repo / "requirements.in").write_text("mkdocs==1.6.1\n", encoding="utf-8")
        result = self.run_gate()
        self.assertEqual(result.returncode, 1)
        self.assertIn("requirements.txt: input requirements.in is not a tracked file",
                      result.stderr)

    def test_prelude_lock_is_named_unchecked_and_no_locks_pass(self):
        """Verify a lock after a prelude is printed as not checked and an empty tree passes."""
        self.track("tools/requirements.txt", "# SPDX\n\n" + UV_HEADER + "mkdocs==1.6.1\n")
        self.track("notes.txt", "plain text\n")
        result = self.run_gate()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("not checked: tools/requirements.txt", result.stdout)
        self.assertIn("pins agree with their inputs: no locks", result.stdout)


if __name__ == "__main__":
    unittest.main()
